"""Shared LVGL component XML and Qt overlay commands for the board gateway."""
XMLUI_SPECS={
 'xmlui.preferences':{'description':'Read or save the default home location used for relevant weather, local news and outdoor air-quality updates. Change it only when the user supplies a location. Five-digit US ZIP code; explicit requests for another location override this default. The default is persisted on the board and returned by xmlui.templates.','required':{},'optional':{'postal_code':{'type':'string','description':'Five-digit US ZIP code; omit parameters to read current setting.'},'country':{'type':'string','description':'US (default).'}},'timeout_ms':10000},
 'xmlui.templates':{'description':'Discover ten reusable smart-home XML templates and their named fields. Each XML simultaneously drives genuine LVGL widgets and Qt translucent visuals in one compositor. Use these templates for smart home/weather/news/energy/security/room/audio display requests. Values labelled SAMPLE are illustrative. For live content retrieve facts and cite sources, then call xmlui.present. Use the location returned by this command for local weather/news/outdoor air quality unless the user explicitly chooses another place. Outdoor AQI does not imply indoor CO2 readings. Do not redraw using old single-tab media commands.','required':{},'optional':{},'timeout_ms':15000},
 'xmlui.present':{'description':'Choose a reusable smart-home XML template and bind AI-produced content to its declared fields. Qt and LVGL layers update together. First consult xmlui.templates, including its default home location for relevant local information. Available templates: home, weather, news, climate, lighting, energy, security, air, scenes, sound. Never invent sensor readings or news; keep simulated home controls labelled demo. Include source/date in source. The presentation option reuses existing photos/slideshow, generated PDF and YouTube/video preparation; Audio/radio stays independent. Use native media.switch or Audio controls to select prepared media.','required':{'template':{'type':'string','description':'One of the ten template IDs.'},'data':{'type':'object','description':'Only declared named fields. Strings up to 4096 bytes. level is a number 0..100. Common fields title, kicker, hero, summary, metric1_label/metric1, metric2_label/metric2, metric3_label/metric3, source, headline1..3, trend (comma-separated chart values), question.'}},'optional':{'presentation':{'type':'object','description':'GenUI v1 presentation: version=1, sourced document with blocks/sources, optional slides [{url,caption,source}], interval_seconds=1, video {kind:youtube,url,caption}. Board generates its PDF; all media downloads and decoding stay on board.'}},'timeout_ms':20000},
 'xmlui.status':{'description':'Read the active XML template, bound values, frame count and both renderers.','required':{},'optional':{},'timeout_ms':10000},
 'audio.autotune':{'description':'Guide a user preference calibration using real NAU8822 five-band EQ at 105/300/850/2400/6900 Hz. FIRST ask whether the user wants to calibrate and wait for consent. Start snapshots original EQ/radio, without playing tones. Let the listener hear A and B (same generated 1.5-second -25 dBFS tone), ASK which sounds better, and WAIT for a/b/same before choose. Ten comparisons, small 3 dB then 1 dB steps, bounded +/-6 dB, fixed headphone volume. Never fabricate a listener choice or run all comparisons automatically. The panel has physical touch buttons too. Cancel restores original settings and prior radio. A preferred preset is saved on completion; this is not microphone-based room measurement.','required':{},'optional':{'operation':{'type':'string','description':'start, a, b, choose, cancel, status'},'choice':{'type':'string','description':'a, b or same; only for choose, after real user feedback.'}},'timeout_ms':20000},
 'audio.tone':{'description':'Generate a short listening tone on board and play it through existing headphone/audio machinery after the user requests a tone. No cloud audio download. Avoid interrupting unrelated playback without a user request. For A/B EQ use audio.autotune instead, which preserves/restores the prior radio and profile.','required':{},'optional':{'frequency_hz':{'type':'number','description':'80..8000 Hz, default 440.'},'duration_seconds':{'type':'number','description':'0.2..3 seconds, default 1.5.'},'level_dbfs':{'type':'number','description':'-36..-18 dBFS, default -25; faded stereo 48 kHz PCM.'}},'timeout_ms':15000}
}
